input.command:
ls sc4sap/configs/*/actions.json && cat > "$TMP/cmp.js" <<'EOF'
const fs=require('fs'),path=require('path');
const root='C:/Users/pssps/Documents/Projects/sc4sap_project/';
const cat={};
for(const m of fs.readdirSync(root+'sc4sap/configs')){const f=root+'sc4sap/configs/'+m+'/actions.json';if(!fs.existsSync(f))continue;const j=JSON.parse(fs.readFileSync(f));for(const a of (j.actions||j))cat[a.id]=Object.fromEntries((a.params||[]).map(p=>[p.name,p.type]));}
const sc=JSON.parse(fs.readFileSync(root+'.sc4sap/work/HKT-DEV/biz-scenarios/scenarios.json'));
const seen={};
for(const s of (sc.scenarios||sc)){const c=cat[s.action];if(!c)continue;for(const[k,v]of Object.entries(s.input||{})){const t=c[k];const isArr=Array.isArray(v);const key=s.action+'.'+k;if(t===undefined){seen[key]=(seen[key]||'')+' [not in catalog]';continue;}if(isArr!==(t||'').endsWith('[]'))seen[key]=`catalog=${t} scenario=${isArr?'array':typeof v}`;}}
console.log(Object.entries(seen).map(e=>e.join('  ')).join('\n')||'none');
EOF
node "$TMP/cmp.js"

