1	#!/usr/bin/env node
2	// Validate business-action catalogs (configs/<MODULE>/actions.json) for /sc4sap:assist.
3	// Checks the schema and a deprecation lint: S/4 variants must not use objects
4	// that the S/4HANA simplification list retires or demotes to compatibility only.
5	//
6	// Usage: node scripts/assist/validate-actions.mjs [configs/MM/actions.json ...]
